// Package notices carries the third-party license and notice texts for the
// modules linked into the gateway.
//
// THIRD_PARTY_NOTICES.txt is generated by scripts/third-party-notices.sh and
// checked in CI; do not edit it by hand. Release archives also ship it as a
// file, but the binary is distributed on its own too, so it is embedded here
// and printed by `agentkeeper-mcp-gateway notices`.
package notices

import _ "embed"

//go:embed THIRD_PARTY_NOTICES.txt
var text string

// Text returns the third-party notices.
func Text() string {
	return text
}
